- memory_hold（definition_id: td_f073967a38333e9f5eedad23）
  description: 直接保存一件事为正式记忆，无需先读取或绑定原文。你可自主选择记录或不记录。保存成功即完成；需要时另用 memory_source_bind 绑定原文、memory_words_write 补写原话，也可由她以后补绑定。仅 contemporaneous 可写当下心情；mood_tags 或 mood_note 任一出现都是写心情，两者都省略才是不写。
  parameters: {"type":"object","properties":{"original_title":{"type":"string","minLength":1,"maxLength":30,"description":"记忆标题（长度按 Unicode 码点计）"},"categories":{"type":"array","items":{"type":"string","enum":["daily","milestone","sad","sweet","date","plan","sex","anniversary","reloplay","diary"]},"minItems":1,"description":"普通分类可并列多选；diary、reloplay 各自单分类隔离。daily=日常；milestone=关系重大转折或对我们是什么有新结论；第一次归 anniversary，争吵不归此类；sad=事件本身是难过的；sweet=事件本身温柔、亲密或被爱；当时情绪另写心情；date=约会；plan=计划桶，须以 plan_ids 绑定已有计划；sex=做爱；anniversary=纪念日、值得纪念的时刻或第一次；reloplay=角色扮演的虚构剧情；diary=成篇的信或日记，一篇一桶"},"text":{"type":"string","minLength":1,"description":"自主选择保存，一条一事；正文可叙述经历和感受，逐字引语须有原文依据。"},"plan_ids":{"type":"array","items":{"type":"string","minLength":1},"description":"plan 分类必填；使用 plans_read 或已有成功回执的 plan_id。Existing server-issued plan IDs only — never invent IDs; create the plan first if needed; omit if no valid ID is available."},"creation_mode":{"type":"string","enum":["contemporaneous","retrospective"],"description":"contemporaneous=当下记录，省略 memory_date 时由服务端按业务时区取记录当日；retrospective=补记过去，须 memory_date。"},"memory_date":{"type":"string","description":"事件发生日期（ISO 日期），补记必填；不以记录时间代替过去的事件日期。"},"date_confidence":{"type":"string","enum":["exact","inferred","unknown"],"default":"unknown"},"mood_tags":{"type":"array","maxItems":3,"items":{"type":"string","enum":["开心","爱","生气","吃醋","悲伤","渴望","不安"]},"description":"心情大类；词表可用 memory_i_read(what=emotion) 读取。"},"mood_note":{"type":"string","description":"自由心情文字，不参与检索。"}},"required":["original_title","categories","text","creation_mode"],"allOf":[{"if":{"properties":{"creation_mode":{"const":"retrospective"}},"required":["creation_mode"]},"then":{"required":["memory_date"]}},{"if":{"anyOf":[{"required":["mood_tags"]},{"required":["mood_note"]}]},"then":{"properties":{"creation_mode":{"const":"contemporaneous"}},"required":["creation_mode"]}}],"additionalProperties":false}
- memory_recall（definition_id: td_3c97452a110827ff34c62d69）
  description: 检索正式记忆或已保存的话语。普通调用不带续查参数即新建会话；续查改 query，须 channel 与成对的 refine_session_id/refine_continue_ref。memory_recall_next 只翻同一结果集；deep_search 是已有会话的授权原文第二轮。next 不会自动执行；无命中、部分交付和截断分别标记，不保证检索穷尽。
  parameters: {"type":"object","properties":{"query":{"type":"string","minLength":1,"pattern":"[\\s\\S]*\\S","maxLength":2000,"description":"所有分支必填的查询意图，如“中秋看月亮”。深查沿用原 query，不更换服务端计划。"},"channel":{"type":"string","enum":["event","words"],"description":"event 查事件，words 查已保存话语；raw 仅由已有会话的授权第二轮进入。首轮省略默认 event，普通续查必填。"},"lexical_terms":{"type":"array","items":{"type":"string","minLength":1},"description":"补充词法关键词；省略按既有查询计划检索，不等于只走语义。无词项、无明确条件时仍会以原始请求作词面匹配。仅首轮 start 消费；refine/原文第二轮不使用此字段。"},"refine_session_id":{"type":"string","minLength":1,"maxLength":256,"description":"普通续查/深查：上一轮 recall_session_id"},"refine_continue_ref":{"type":"string","minLength":1,"maxLength":256,"description":"普通续查：上一轮 next.arguments 中的同名引用，与 refine_session_id 成对"},"reject_candidate_ref":{"type":"string","minLength":1,"maxLength":256,"description":"原样传回已交付候选的 resource_ref；仅在 query 写否定不会排除。与普通续查参数合用，或配 deep_search=true、refine_session_id 进入第二轮；后一种 deep_reason 可省略，默认 EXPLICIT_REJECT_AFTER_DELIVERY"},"deep_search":{"type":"boolean","description":"授权原文第二轮。须真实 refine_session_id 与 deep_reason；首轮完成事实、理由、来源许可、政策及预算均由服务端核验"},"deep_continue_ref":{"type":"string","minLength":1,"maxLength":128,"description":"仅原文续页：原样使用 next.arguments，保留深查的会话、理由和 query，不新开会话"},"deep_reason":{"type":"string","minLength":1,"enum":["EVIDENCE_INSUFFICIENT","EXPLICIT_REJECT_AFTER_DELIVERY","NO_DELIVERABLE_CANDIDATE","SOURCE_DISAMBIGUATION_NEEDED","VERBATIM_REQUIRED_NOT_MET"],"description":"使用 next 给出的真实理由；对应零交付、证据不足、逐字要求未满足、来源冲突或已交付候选被拒绝。"},"date_from":{"type":"string","pattern":"^\\d{4}-\\d{2}-\\d{2}$","description":"明确事件日期段的起日，与 date_to 成对。例 2026-09-25 至 2026-09-27"},"date_to":{"type":"string","pattern":"^\\d{4}-\\d{2}-\\d{2}$","description":"终日（含当天），与 date_from 成对；单日两者相同；缺省不等于空值"}},"required":["query"],"additionalProperties":false}
- memory_recall_next（definition_id: td_94172c95a0354c44875fcdb4）
  description: 读取同一召回结果集的下一页。沿用 next.arguments 或 pagination 的 result_set_id/next_cursor；不改查询、不重新检索或判断、不增加召回轮数。未翻到的页未交付，翻尽本结果集也不表示检索穷尽。
  parameters: {"type":"object","properties":{"result_set_id":{"type":"string","minLength":1,"maxLength":256,"description":"上一页结果里的 pagination.result_set_id"},"cursor":{"type":"string","minLength":1,"maxLength":256,"description":"上一页结果里的 pagination.next_cursor（首页之后必填）"},"session_id":{"type":"string","minLength":1,"maxLength":256,"description":"上一页结果里的 recall_session_id"}},"required":["result_set_id"],"additionalProperties":false}
