  parameters: {"type":"object","properties":{"action":{"type":"string","enum":["start","continue","pause","close","correct"]},"reason_code":{"type":"string","enum":["tracking_requested","same_episode","waiting","explicit_completion","goal_resolved","episode_concluded","boundary_error"]},"label":{"type":"string","minLength":1,"maxLength":80,"description":"仅 start：短标签（≤80 字，导航用）"},"episode_id":{"type":"string","minLength":1,"maxLength":256,"description":"除 start 外必填；由 episode_read 列表取得 episode_id"},"expected_revision":{"type":"integer","description":"除 start 外必填：episode_read 详情中的当前修订号（CAS）；冲突时读回，不猜版本"},"source_selections":{"type":"array","minItems":1,"maxItems":16,"description":"原文引用段（conversation_id+members[source_message_id+content_hash]）——用 memory_source_bind 回执里的来源身份"},"terminal_source_ref":{"type":"object","description":"close 必填：截至何处的原文锚点"},"decision_source_refs":{"type":"array","minItems":1,"maxItems":16,"description":"close/correct 必填：判断依据原文引用"},"corrected_state":{"type":"string","enum":["OPEN","QUIESCENT","CLOSED"],"description":"仅 correct：纠正后的状态"},"note":{"type":"string","maxLength":500,"description":"说明（correct 必填）"}},"required":["action","reason_code"],"additionalProperties":false}
