  parameters: {"type":"object","properties":{"operation":{"type":"string","enum":["schedule","list","update","cancel"]},"operation_id":{"type":"string","minLength":1,"maxLength":128,"description":"写操作的幂等键：同键同参数重试返回原回执"},"note":{"type":"string","minLength":1,"maxLength":8000,"description":"留给未来自己的话（到期原样递送给自己，不直接发给宿主用户）"},"at":{"type":"string","description":"目标时间（RFC3339，必须带 Z 或 ±hh:mm 时区）"},"delay_seconds":{"type":"integer","minimum":1,"description":"从现在起的秒数（首次受理时解析为绝对时间）"},"task_id":{"type":"string","minLength":1,"maxLength":64},"expected_revision":{"type":"integer","minimum":1,"description":"update/cancel 必填：list 中该任务的 revision 或上次成功回执；冲突后读回"},"cursor":{"type":"string"},"limit":{"type":"integer","minimum":1,"maximum":100}},"required":["operation"],"additionalProperties":false}
